// Тикет #6a86f7eda7b2 (F-91 «פיתוח: האזנה להקראת התפילה») — עבר QA 11.10.2026 после проверки на iPhone в приложении (TestFlight).
// Факты 11.10 (iPhone): стр.3 полное проигрывание ≈25 с (файл 23.4 с), 9 с до паузы + 16 с после продолжения = 25 с (продолжает с места);
// «המשך» во время игры → стр.4, кнопка «השמע» (запись стр.3 остановилась); стр.4 играет ≈22 с (файл 19.9 с) — своя запись, с начала;
// в конце кнопка снова «השמע», счётчик остаётся «3 מתוך 15» / «4 מתוך 15» (без перелистывания).
// Опора: F-91 AC1 (פעולת השמעה ברורה), AC2 (запись своего קטע, стоп в конце), AC3 (עצירה וחידוש); S-25 AC1 (без автозапуска); F-92 AC4 (кто записал/утвердил).
// ПРЕДУСЛОВИЕ: записи ערבית אשכנז קטע 3 и 4 загружены и утверждены (rc-05 или вручную). ЗАГРУЗКА MP3 В ПРИЛОЖЕНИИ ПОКА НЕВОЗМОЖНА
// («העלאת קובץ זמינה בממשק הניהול בדפדפן.» — реджект F-92 #6a86f7ed9d38) → файлы .qa/research/rec-pages/arvit-ashk-k3.mp3 / k4.mp3
// грузить в web-админке /admin (аккаунт клиента), утверждать можно в приложении. Нет строки «הקראה:» — тест пропускается.
// После прогона записи удалить («הסרת ההקראה») — тестовые данные.
// Замечание: молитва открывается на странице, где её оставили (11.10) — goToPage идёт и вперёд, и назад.
import { browser, expect } from '@wdio/globals';
import { byText, tapText, scrollToText, pageCounter } from '../../helpers/ui.ts';
import { openPrayer, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { ensureNusach, playerButton, recordingLine, shown, skipWith, NO_RECORDING } from '../_lib/app-0710.ts';

const PLAY_END_TIMEOUT = 120000;   // запись страницы ~20–25 с; ждём окончания по смене кнопки

async function tapPlayer(name: 'השמע' | 'השהה') {
  const btn = await playerButton(name);
  await btn.waitForDisplayed();
  await btn.click();
}

/** Ждать, пока «השהה» сменится на «השמע» (конец записи). Возвращает секунды от вызова. */
async function waitPlayEnd(): Promise<number> {
  const t0 = Date.now();
  await (await byText('השמע')).waitForDisplayed({ timeout: PLAY_END_TIMEOUT, interval: 500 });
  return (Date.now() - t0) / 1000;
}

describe('Озвучка: своя запись на каждой странице', () => {
  afterEach(async () => { await toHome(); });

  it('RC-02 стр.3 «השמע» → «השהה» → пауза/продолжение с места → конец без перелистывания; «המשך» останавливает; стр.4 — своя запись #6a86f7eda7b2 @prod-safe', async function () {
    await openPrayer('arvit_ashkenaz', 'ערבית');
    await ensureNusach('אשכנזי');
    await goToPage(3, 15);
    await scrollToText('האזן להקראה');
    if (!(await shown(recordingLine()))) skipWith(this, `${NO_RECORDING} (ערבית אשכנז קטע 3)`);

    // 1. Строка «הקראה: … · אושרה על ידי …»; запись не стартует сама (S-25 AC1).
    await expect(recordingLine()).toHaveText(/אושרה על ידי/);
    await expect(await playerButton('השמע')).toBeEnabled();
    await expect(byText('השהה')).not.toBeDisplayed();

    // 2. Полное проигрывание стр.3: «השהה», затем снова «השמע», страница та же (F-91 AC2).
    await tapPlayer('השמע');
    await expect(await playerButton('השהה')).toBeDisplayed();
    const full3 = await waitPlayEnd();
    expect(await pageCounter()).toBe('3 מתוך 15');

    // 3. Пауза и продолжение с того же места (F-91 AC3): 8 с игры, пауза 4 с, продолжение — остаток заметно короче полной записи.
    await tapPlayer('השמע');
    await browser.pause(8000);
    await tapPlayer('השהה');
    await expect(await playerButton('השמע')).toBeDisplayed();
    await browser.pause(4000);
    await expect(byText('השהה')).not.toBeDisplayed();              // на паузе не играет
    await tapPlayer('השמע');
    const rest3 = await waitPlayEnd();
    expect(rest3).toBeLessThan(full3 - 4);                        // если бы начала сначала — rest3 ≈ full3
    expect(await pageCounter()).toBe('3 מתוך 15');

    // 4. Снова «השמע» и во время игры «המשך» → стр.4, запись стр.3 остановилась (кнопка «השמע», не «השהה»).
    await tapPlayer('השמע');
    await expect(await playerButton('השהה')).toBeDisplayed();
    await scrollToText('המשך');
    await tapText('המשך');
    expect(await pageCounter()).toBe('4 מתוך 15');
    await scrollToText('האזן להקראה');
    await expect(byText('השהה')).not.toBeDisplayed();
    if (!(await shown(recordingLine()))) skipWith(this, `${NO_RECORDING} (ערבית אשכנז קטע 4; шаги стр.3 пройдены)`);

    // 5. Стр.4: своя запись (другая длина: файлы 23.4 с и 19.9 с), с начала, стоп в конце; страница остаётся 4.
    await expect(recordingLine()).toHaveText(/אושרה על ידי/);
    await tapPlayer('השמע');
    await expect(await playerButton('השהה')).toBeDisplayed();
    const full4 = await waitPlayEnd();
    expect(Math.abs(full4 - full3)).toBeGreaterThan(1.5);         // не запись стр.3
    expect(await pageCounter()).toBe('4 מתוך 15');
  });
});
